SELECT IIf([TransactionID]=DMin("TransactionID","Transaction","AccountID = " & [AccountID] & ""),0,Val(DSum("Balance","Transaction","[TransactionID] <= " & [TransactionID] & " and AccountID = " & [AccountID] & ""))) AS RunningZero, Val(DSum("[Balance]","Transaction","[TransactionID] <= " & [TransactionID] & " and [AccountID] = " & [AccountID] & "")) AS RunningSum, Val(DCount("[Balance]","Transaction","[TransactionID] <= " & [TransactionID] & " and AccountID = " & [AccountID] & "")) AS RunningCount, Transaction.TransactionID AS Expr1, Transaction.Trans_Head AS Expr2, Transaction.TransactionDate AS [Date], Transaction.TransactionDescription AS Expr3, Transaction.AccountID AS Expr4, Transaction.Credit AS Expr5, Transaction.Debit AS Expr6, Transaction.Balance AS Expr7, Transaction.OK AS Expr8, VoucherType.VoucherTypeCode & "-" & Trans_Head.VoucherNo AS VoucherNo
FROM VoucherType, Trans_head, [Transaction];

